import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String user_input = scanner.nextLine();
        char initial_char = user_input.charAt(0);
        String modified_part = user_input.substring(1).replace("dot", ".");
        String combined = initial_char + modified_part;
        if (combined.endsWith(".")) {
            combined = combined.substring(0, combined.length() - 1) + "dot";
        }
        initial_char = combined.charAt(0);
        String remaining = combined.substring(1).replaceFirst("at", "@");
        if (remaining.endsWith("@")) {
            remaining = remaining.substring(0, remaining.length() - 1) + "at";
        }
        System.out.println(initial_char + remaining);
    }
}
